      const source=paired?`<div class="sch-can-pair">${pairPicker('线芯 1',owner.from,'from')}${pairPicker('线芯 2',owner.pairFrom,'pairFrom')}</div>`:pickerHtml(owner.from,'from');
      const targets=display.targets.map((entry,targetIndex)=>{const targetOwner=entry.wire,t=entry.target,targetPaired=targetOwner.type==='can';return`<div class="sch-target${targetPaired?' sch-can-target':''}" data-target-row="${t.id}" data-wire-id="${targetOwner.id}"><span>${targetIndex+1}</span>${targetPaired?`<div class="sch-can-pair">${pairPicker('线芯 1',t.to,'target',t.id)}${pairPicker('线芯 2',t.pairTo,'pairTarget',t.id)}</div>`:pickerHtml(t.to,'target',t.id)}<button class="btn sch-add-junction" data-add-junction-target="${t.id}" title="在该线路中间插入可分支的连接点">＋中间点</button>${targetIndex===0?`<button class="btn sch-add-target" data-add-target="${owner.id}">＋终点</button>`:'<span class="sch-target-action-spacer"></span>'}<button class="row-del" data-delete-target="${t.id}"${targetOwner.targets.length===1?' disabled':''}>×</button></div>`;}).join('');
      const can=owner.type==='can',complete=!can||canPairComplete(owner),classes=`sch-connection-subrow${rowIndex?' sch-connection-subrow-branch sch-wire-branch-row':''}${can?` sch-can-row${complete?'':' sch-can-incomplete'}`:''}`;
