  function setCanvasZoom(value){state.meta.canvasZoom=clamp(Math.round(Number(value)*20)/20,.2,2);const slider=host.querySelector('#schZoom'),label=host.querySelector('#schZoomValue'),dynamic=host.querySelector('#schDynamicStyles');if(slider)slider.value=Math.round(state.meta.canvasZoom*100);if(label)label.value=label.textContent=`${Math.round(state.meta.canvasZoom*100)}%`;if(dynamic)dynamic.textContent=dynamicStyles()+wireWorkspaceStyles();}
